int **zigzagLevelOrder(struct TreeNode *root, int *returnSize, int **returnColumnSizes) {
  if (root == NULL) {
    *returnSize = 0;
    *returnColumnSizes = NULL;
    return NULL;
  }

  int capacity = 16;
  int **res = (int **)malloc(sizeof(int *) * capacity);
  *returnColumnSizes = (int *)malloc(sizeof(int) * capacity);

  struct TreeNode **queue = (struct TreeNode **)malloc(sizeof(struct TreeNode *) * 2001);
  int front = 0, back = 0, level = 0;
  queue[back++] = root;

  while (front < back) {
    int size = back - front;
    if (level >= capacity) {
      capacity *= 2;
      res = (int **)realloc(res, sizeof(int *) * capacity);
      *returnColumnSizes = (int *)realloc(*returnColumnSizes, sizeof(int) * capacity);
    }
    res[level] = (int *)malloc(sizeof(int) * size);
    (*returnColumnSizes)[level] = size;
    for (int i = 0; i < size; i++) {
      struct TreeNode *node = queue[front++];
      if (level % 2 == 0) {
        res[level][i] = node->val;
      } else {
        res[level][size - 1 - i] = node->val;
      }
      if (node->left != NULL) queue[back++] = node->left;
      if (node->right != NULL) queue[back++] = node->right;
    }
    level++;
  }

  *returnSize = level;
  free(queue);
  return res;
}

class Solution {
public:
  vector<vector<int>> zigzagLevelOrder(TreeNode *root) {
    vector<vector<int>> res;
    if (root == nullptr) return res;
    queue<TreeNode *> q;
    q.push(root);
    while (!q.empty()) {
      int size = q.size();
      vector<int> level;
      for (int i = 0; i < size; i++) {
        TreeNode *node = q.front();
        q.pop();
        level.push_back(node->val);
        if (node->left) q.push(node->left);
        if (node->right) q.push(node->right);
      }
      if (res.size() % 2 == 1) reverse(level.begin(), level.end());
      res.push_back(level);
    }
    return res;
  }
};

func zigzagLevelOrder(root *TreeNode) [][]int {
	var res [][]int
	if root == nil {
		return res
	}
	queue := []*TreeNode{root}
	for len(queue) > 0 {
		size := len(queue)
		level := make([]int, 0, size)
		for i := 0; i < size; i++ {
			node := queue[0]
			queue = queue[1:]
			level = append(level, node.Val)
			if node.Left != nil {
				queue = append(queue, node.Left)
			}
			if node.Right != nil {
				queue = append(queue, node.Right)
			}
		}
		if len(res)%2 == 1 {
			for i, j := 0, len(level)-1; i < j; i, j = i+1, j-1 {
				level[i], level[j] = level[j], level[i]
			}
		}
		res = append(res, level)
	}
	return res
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  public List<List<Integer>> zigzagLevelOrder(TreeNode root) {
    List<List<Integer>> res = new ArrayList<>();
    if (root == null) {
      return res;
    }
    Queue<TreeNode> queue = new LinkedList<>();
    queue.offer(root);
    while (!queue.isEmpty()) {
      int size = queue.size();
      List<Integer> level = new ArrayList<>();
      for (int i = 0; i < size; i++) {
        TreeNode node = queue.poll();
        level.add(node.val);
        if (node.left != null) queue.offer(node.left);
        if (node.right != null) queue.offer(node.right);
      }
      if (res.size() % 2 == 1) {
        Collections.reverse(level);
      }
      res.add(level);
    }
    return res;
  }
}

class Solution:
    def zigzagLevelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        res = []
        if root is None:
            return res
        queue = [root]
        while queue:
            size = len(queue)
            level = []
            for _ in range(size):
                node = queue.pop(0)
                level.append(node.val)
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            if len(res) % 2 == 1:
                level.reverse()
            res.append(level)
        return res

use std::collections::VecDeque;

impl Solution {
  pub fn zigzag_level_order(root: Option<Box<TreeNode>>) -> Vec<Vec<i32>> {
    let mut res: Vec<Vec<i32>> = vec![];
    let root_ref = match root.as_ref() {
      Some(node) => node.as_ref(),
      None => return res,
    };
    let mut queue: VecDeque<&TreeNode> = VecDeque::new();
    queue.push_back(root_ref);
    while !queue.is_empty() {
      let size = queue.len();
      let mut level = vec![];
      for _ in 0..size {
        let node = queue.pop_front().unwrap();
        level.push(node.val);
        if let Some(left) = node.left.as_ref() {
          queue.push_back(left.as_ref());
        }
        if let Some(right) = node.right.as_ref() {
          queue.push_back(right.as_ref());
        }
      }
      if res.len() % 2 == 1 {
        level.reverse();
      }
      res.push(level);
    }
    res
  }
}

const zigzagLevelOrder = (root: TreeNode | null): number[][] => {
  const res: number[][] = [];
  if (!root) return res;
  const queue: TreeNode[] = [root];
  while (queue.length > 0) {
    const size = queue.length;
    const level: number[] = [];
    for (let i = 0; i < size; i++) {
      const node = queue.shift()!;
      level.push(node.val);
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
    if (res.length % 2 === 1) level.reverse();
    res.push(level);
  }
  return res;
};
